import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.C-KFX0n7.js";const p=JSON.parse('{"title":"Integrasi API Teken Heula","description":"Panduan integrasi API Teken Heula (layanan e-sign/e-seal BSrE Universitas Pendidikan Indonesia) — endpoint /api/sign-language-certs, /api/sign-mandala, /api/sign-sakip, /api/sign-eplanning. Gunakan saat menulis, men-debug, atau me-review kode yang mengirim dokumen PDF ke Teken Heula untuk ditandatangani/disegel, memantau statusnya, atau mengunduh PDF hasilnya (teken.upi.edu, Bearer token Sanctum, payload doc/eseal/esign, signature_properties, error 401/403/422/400).","frontmatter":{"name":"teken-heula-api","description":"Panduan integrasi API Teken Heula (layanan e-sign/e-seal BSrE Universitas Pendidikan Indonesia) — endpoint /api/sign-language-certs, /api/sign-mandala, /api/sign-sakip, /api/sign-eplanning. Gunakan saat menulis, men-debug, atau me-review kode yang mengirim dokumen PDF ke Teken Heula untuk ditandatangani/disegel, memantau statusnya, atau mengunduh PDF hasilnya (teken.upi.edu, Bearer token Sanctum, payload doc/eseal/esign, signature_properties, error 401/403/422/400)."},"headers":[],"relativePath":"public/skills/teken-heula-api/SKILL.md","filePath":"public/skills/teken-heula-api/SKILL.md"}'),d={name:"public/skills/teken-heula-api/SKILL.md"};function l(s,e,o,r,g,c){return t(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="integrasi-api-teken-heula" tabindex="-1">Integrasi API Teken Heula <a class="header-anchor" href="#integrasi-api-teken-heula" aria-label="Permalink to &quot;Integrasi API Teken Heula&quot;">​</a></h1><p>Teken Heula adalah layanan tanda tangan elektronik (e-sign) dan segel elektronik (e-seal) UPI yang tersertifikasi BSrE. Sistem lain mengirim PDF (base64) via API, dokumen diproses <strong>asynchronous</strong> di antrean server, lalu PDF hasil diunduh.</p><h2 id="pilih-modul-yang-tepat" tabindex="-1">Pilih modul yang tepat <a class="header-anchor" href="#pilih-modul-yang-tepat" aria-label="Permalink to &quot;Pilih modul yang tepat&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Modul</th><th style="text-align:left;">Untuk dokumen</th><th style="text-align:left;">Endpoint dasar</th><th style="text-align:left;">E-seal?</th><th style="text-align:left;">Penandatangan</th><th style="text-align:left;">Detail</th></tr></thead><tbody><tr><td style="text-align:left;">Language Cert</td><td style="text-align:left;">Sertifikat bahasa (Balai Bahasa)</td><td style="text-align:left;"><code>/api/sign-language-certs</code></td><td style="text-align:left;">✅ Ya, sebelum e-sign</td><td style="text-align:left;">Tepat 1</td><td style="text-align:left;"><a href="./references/language-cert.html">references/language-cert.md</a></td></tr><tr><td style="text-align:left;">Mandala</td><td style="text-align:left;">Surat/dokumen resmi Mandala</td><td style="text-align:left;"><code>/api/sign-mandala</code></td><td style="text-align:left;">❌</td><td style="text-align:left;">≥ 1</td><td style="text-align:left;"><a href="./references/mandala.html">references/mandala.md</a></td></tr><tr><td style="text-align:left;">SAKIP</td><td style="text-align:left;">Dokumen akuntabilitas kinerja (Renstra, RKT, PK, LKjIP)</td><td style="text-align:left;"><code>/api/sign-sakip</code></td><td style="text-align:left;">❌</td><td style="text-align:left;">≥ 1, berjenjang</td><td style="text-align:left;"><a href="./references/sakip.html">references/sakip.md</a></td></tr><tr><td style="text-align:left;">e-Planning</td><td style="text-align:left;">RKAT dari aplikasi e-Planning</td><td style="text-align:left;"><code>/api/sign-eplanning</code></td><td style="text-align:left;">❌</td><td style="text-align:left;">≥ 1, berjenjang</td><td style="text-align:left;"><a href="./references/eplanning.html">references/eplanning.md</a></td></tr></tbody></table><p>Baca file reference modul yang dipakai sebelum menulis payload — nama field <code>doc</code> berbeda per modul. Untuk penanganan error lengkap lihat <a href="./references/errors.html">references/errors.md</a>; contoh client siap pakai (Laravel, Node.js, Python) ada di <a href="./references/client-examples.html">references/client-examples.md</a>.</p><h2 id="koneksi" tabindex="-1">Koneksi <a class="header-anchor" href="#koneksi" aria-label="Permalink to &quot;Koneksi&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Lingkungan</th><th style="text-align:left;">Base URL</th></tr></thead><tbody><tr><td style="text-align:left;">Production</td><td style="text-align:left;"><code>https://teken.upi.edu/api</code></td></tr><tr><td style="text-align:left;">Development (lokal)</td><td style="text-align:left;"><code>http://localhost:8000/api</code></td></tr></tbody></table><p>Header wajib di setiap request:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer &lt;TOKEN&gt;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/json</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Accept</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/json</span></span></code></pre></div><ul><li>Token didapat dari halaman profil (menu API Token) di aplikasi Teken Heula. Simpan di environment variable (mis. <code>TEKEN_HEULA_TOKEN</code>, <code>TEKEN_HEULA_BASE_URL</code>) — <strong>jangan pernah hardcode atau commit token</strong>.</li><li>Token saja tidak cukup: akun juga butuh permission per modul, <code>ApiCreate:&lt;Doc&gt;</code>, <code>ApiUpdate:&lt;Doc&gt;</code>, <code>ApiView:&lt;Doc&gt;</code> dengan <code>&lt;Doc&gt;</code> = <code>DocLanguageCert</code> / <code>DocMandala</code> / <code>DocSakip</code> / <code>DocEplanning</code>. Tanpa itu → <code>403</code>.</li><li>Rate limit: <strong>200 request/menit per token</strong>. Lebih dari itu → <code>429</code>.</li><li>Selalu kirim <code>Accept: application/json</code> supaya error validasi kembali sebagai JSON <code>422</code>, bukan redirect HTML.</li></ul><h2 id="empat-endpoint-pola-sama-di-semua-modul" tabindex="-1">Empat endpoint (pola sama di semua modul) <a class="header-anchor" href="#empat-endpoint-pola-sama-di-semua-modul" aria-label="Permalink to &quot;Empat endpoint (pola sama di semua modul)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Aksi</th><th style="text-align:left;">Method &amp; path</th><th style="text-align:left;">Hasil</th></tr></thead><tbody><tr><td style="text-align:left;">Ajukan dokumen</td><td style="text-align:left;"><code>POST /sign-&lt;modul&gt;</code></td><td style="text-align:left;"><code>200</code> + <code>data.doc.document_id</code> (UUID)</td></tr><tr><td style="text-align:left;">Revisi dokumen</td><td style="text-align:left;"><code>PUT /sign-&lt;modul&gt;/{documentId}</code></td><td style="text-align:left;"><code>200</code> + data terbaru</td></tr><tr><td style="text-align:left;">Cek status</td><td style="text-align:left;"><code>GET /sign-&lt;modul&gt;/{documentId}</code></td><td style="text-align:left;"><code>200</code> + <code>esign[].status</code> + <code>latest_timeline_status</code></td></tr><tr><td style="text-align:left;">Unduh PDF</td><td style="text-align:left;"><code>GET /sign-&lt;modul&gt;/{documentId}/file</code></td><td style="text-align:left;"><code>200</code> <code>application/pdf</code> (binary)</td></tr></tbody></table><p><code>{documentId}</code> harus UUID; selain UUID → <code>404</code>.</p><h2 id="alur-integrasi-yang-benar" tabindex="-1">Alur integrasi yang benar <a class="header-anchor" href="#alur-integrasi-yang-benar" aria-label="Permalink to &quot;Alur integrasi yang benar&quot;">​</a></h2><ol><li><strong>POST</strong> dokumen → simpan <code>data.doc.document_id</code> di database Anda, terhubung ke record lokal. Ini satu-satunya kunci untuk semua request berikutnya.</li><li><strong>Tunggu proses</strong> (asynchronous). Penandatangan menandatangani lewat panel admin Teken Heula, jadi waktunya bisa menit sampai hari — bukan detik — terutama untuk modul berjenjang.</li><li><strong>Polling GET</strong> status dengan interval wajar (mis. tiap 1–5 menit via scheduler/queue job, bukan loop ketat di request user). Dokumen selesai jika <strong>semua</strong> item <code>latest_timeline_status</code> bernilai <code>is_completed: true</code> (untuk modul e-sign: semua <code>esign[].status.value == &quot;finished_signing&quot;</code>; Language Cert juga <code>doc.eseal_status == &quot;sealed&quot;</code>).</li><li><strong>GET .../file</strong> → simpan binary PDF. Jika belum selesai server membalas <code>400</code> — perlakukan sebagai &quot;belum siap&quot;, bukan kegagalan permanen.</li></ol><h2 id="aturan-payload-yang-sering-salah" tabindex="-1">Aturan payload yang sering salah <a class="header-anchor" href="#aturan-payload-yang-sering-salah" aria-label="Permalink to &quot;Aturan payload yang sering salah&quot;">​</a></h2><ul><li><code>file_base64</code> dan <code>imageBase64</code> adalah <strong>base64 murni</strong> — tanpa prefix <code>data:application/pdf;base64,</code> / <code>data:image/png;base64,</code>, tanpa baris baru. PDF harus PDF valid; gambar harus PNG/JPG valid.</li><li><code>esign</code> adalah <strong>array</strong>, walaupun hanya satu penandatangan.</li><li>Dalam satu request: <code>order</code> harus unik (integer ≥ 1), <code>nip</code> tidak boleh duplikat, dan <code>signature_properties.tag</code> tidak boleh duplikat.</li><li><code>signature_properties.tag</code> adalah teks penanda (mis. <code>#</code>, <code>$</code>) yang <strong>benar-benar ada di dalam PDF</strong> pada posisi tanda tangan; BSrE menaruh tanda tangan di posisi tag tersebut. <code>width</code>/<code>height</code> numerik ≥ 1 (pixel). <code>reason</code>/<code>location</code> opsional.</li><li><code>nip</code> penandatangan/penyegel harus terdaftar di Sinergi (SDM UPI). NIP yang belum dikenal akan disinkronkan otomatis; jika gagal → <code>422</code> pada <code>esign.N.nip</code> / <code>eseal.nip</code>.</li><li>Jangan kirim <code>document_id</code> saat POST — server selalu membuat UUID baru.</li><li><code>PUT</code> di Mandala/SAKIP/e-Planning adalah <strong>penggantian penuh</strong>: kirim ulang seluruh <code>doc</code> dan seluruh <code>esign</code>; daftar penandatangan diganti dan urutan dimulai lagi dari <code>order: 1</code>. Hanya Language Cert yang mendukung partial update (lihat reference-nya).</li><li>Jika jaringan memblokir <code>PUT</code>, kirim <code>POST</code> ke path yang sama dengan header <code>X-HTTP-Method-Override: PUT</code>.</li></ul><h2 id="penanganan-error-ringkas" tabindex="-1">Penanganan error ringkas <a class="header-anchor" href="#penanganan-error-ringkas" aria-label="Permalink to &quot;Penanganan error ringkas&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Kode</th><th style="text-align:left;">Arti</th><th style="text-align:left;">Tindakan di kode</th></tr></thead><tbody><tr><td style="text-align:left;"><code>400</code></td><td style="text-align:left;">Download sebelum PDF siap</td><td style="text-align:left;">Coba lagi nanti (polling)</td></tr><tr><td style="text-align:left;"><code>401</code></td><td style="text-align:left;">Token hilang/salah/dicabut</td><td style="text-align:left;">Jangan retry; minta token baru, alert ke admin integrasi</td></tr><tr><td style="text-align:left;"><code>403</code></td><td style="text-align:left;">Permission modul tidak ada</td><td style="text-align:left;">Jangan retry; minta admin Teken Heula menambah permission</td></tr><tr><td style="text-align:left;"><code>404</code></td><td style="text-align:left;"><code>documentId</code> tidak ada / bukan UUID</td><td style="text-align:left;">Periksa ID yang tersimpan</td></tr><tr><td style="text-align:left;"><code>422</code></td><td style="text-align:left;">Validasi gagal</td><td style="text-align:left;">Baca <code>errors</code> (key = path field, mis. <code>esign.0.nip</code>), perbaiki payload; jangan retry payload yang sama</td></tr><tr><td style="text-align:left;"><code>429</code></td><td style="text-align:left;">Rate limit</td><td style="text-align:left;">Backoff lalu retry</td></tr><tr><td style="text-align:left;"><code>5xx</code> / timeout</td><td style="text-align:left;">Gangguan server</td><td style="text-align:left;">Retry dengan exponential backoff; POST hanya di-retry jika yakin request sebelumnya tidak tercatat (cek dulu, hindari dokumen ganda)</td></tr></tbody></table><p>Respons error berbentuk <code>{&quot;message&quot;: &quot;...&quot;, &quot;errors&quot;: {&quot;&lt;field&gt;&quot;: [&quot;pesan&quot;]}}</code> (field <code>errors</code> hanya untuk <code>422</code>). Pesan validasi berbahasa Indonesia.</p><h2 id="saat-menulis-kode-integrasi" tabindex="-1">Saat menulis kode integrasi <a class="header-anchor" href="#saat-menulis-kode-integrasi" aria-label="Permalink to &quot;Saat menulis kode integrasi&quot;">​</a></h2><ul><li>Bungkus API dalam satu client/service kecil (base URL + token dari config, timeout ~60 detik karena payload base64 besar), lalu pakai dari job/queue — bukan dari request HTTP user secara langsung.</li><li>Simpan <code>document_id</code>, status terakhir, dan waktu cek terakhir di tabel lokal; jadikan proses polling + download idempoten.</li><li>Jangan log isi <code>file_base64</code>, <code>imageBase64</code>, atau token. Log cukup <code>document_id</code>, kode status, dan <code>message</code>.</li><li>Sesuaikan nama field <code>doc</code> dengan modul — contoh: Language Cert memakai <code>certificate_number</code>, Mandala memakai <code>mandala_doc_id</code>, SAKIP/e-Planning memakai <code>doc_number</code> + <code>doc_information</code>.</li></ul>`,22)])])}const k=a(d,[["render",l]]);export{p as __pageData,k as default};
